package main

import (
	"fmt"
	"strings"
)

func renderSearchFeedbackEventTypeDart(values []string) string {
	var b strings.Builder
	b.WriteString(
		"// Code generated by tools/codegen_app_metadata from _shared/types.yaml. DO NOT EDIT.\n\n",
	)
	b.WriteString("enum SearchFeedbackEventType {\n")
	for index, value := range values {
		separator := ","
		if index == len(values)-1 {
			separator = ";"
		}
		b.WriteString(
			fmt.Sprintf("  %s('%s')%s\n", toDartValueName(value), value, separator),
		)
	}
	b.WriteString("\n")
	b.WriteString("  const SearchFeedbackEventType(this.wireValue);\n\n")
	b.WriteString("  final String wireValue;\n")
	b.WriteString("}\n")
	return b.String()
}
